var OPEN=['你','今天的你','认真起来的你','温柔的你','努力的你'];
var MID=['的想法比代码还优雅','笑起来很好看','存在让世界更亮了一点','好奇心是你的超能力','坚持正在悄悄开花'];
var TAIL=['。','，值得被好好对待。','，已经做得足够好了。','，有人因为你而安心。'];
function make(seed){ var r=rngFactory(seed); var o=OPEN[Math.floor(r()*OPEN.length)]; var m=MID[Math.floor(r()*MID.length)]; var t=TAIL[Math.floor(r()*TAIL.length)]; return o+m+t; }
function batch(seed,n){ n=n||5; var out=[]; for(var i=0;i<n;i++) out.push(make(seed+i*104729)); return out; }
var EXPORTS={make:make,batch:batch,OPEN:OPEN,MID:MID,TAIL:TAIL};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ComplimentForgePure = EXPORTS; }
